interface CheckoutModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}

const CheckoutModal: React.FC<CheckoutModalProps> = ({ isOpen, onClose, onSuccess }) => {
    const [isLoading, setIsLoading] = useState(false);
    const [view, setView] = useState<'offer' | 'processing' | 'success'>('offer');
    const [webhookLog, setWebhookLog] = useState<string>('');

    if (!isOpen) return null;

    const handleOpenCheckout = () => {
        setIsLoading(true);
        // Simula abertura do link externo
        window.open(KIRVANO_CONFIG.CHECKOUT_URL, '_blank');

        // Muda para tela de "Aguardando Confirmação"
        setTimeout(() => {
            setIsLoading(false);
            setView('processing');
        }, 1000);
    };

    const handleSimulateWebhook = async () => {
        setWebhookLog("Iniciando simulação de Webhook...");
        setIsLoading(true);

        // Gera payload falso
        const payload = generateTestPayload();
        setWebhookLog(prev => prev + `\nEnviando evento: ${payload.event}...`);

        // Processa como se fosse o servidor
        try {
            const result = await processWebhook(payload);
            setWebhookLog(prev => prev + `\nResposta do Servidor: ${result.message}`);

            if (result.success) {
                setTimeout(() => {
                    setView('success');
                    setTimeout(() => {
                        onSuccess();
                        setView('offer');
                        setWebhookLog('');
                    }, 2000);
                }, 1000);
            }
        } catch (e) {
            setWebhookLog(prev => prev + `\nErro: Falha ao processar webhook.`);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-fade-in">
