/**
 * Verifica se o usuário retornou da página de pagamento com sucesso.
 * Procura por ?status=success na URL.
 */
export const checkPaymentRedirect = (): boolean => {
    if (typeof window === 'undefined') return false;

    const params = new URLSearchParams(window.location.search);
    const status = params.get('status');

    if (status === 'success') {
        console.log("Pagamento detectado via URL Redirection");

        // Limpa a URL para o usuário não ficar vendo ?status=success
        const newUrl = window.location.protocol + "//" + window.location.host + window.location.pathname;
        window.history.replaceState({ path: newUrl }, '', newUrl);

        // Ativa o plano
        db.user.login();
        localStorage.setItem('agroconectaIsSubscribed', 'true');
        return true;
    }

    return false;
};

// Mantemos o simulador de Webhook para testes manuais se necessário
export const processWebhook = async (payload: KirvanoWebhookPayload) => {
    if (payload.event === 'sale.approved') {
        localStorage.setItem('agroconectaIsSubscribed', 'true');
        return { success: true, message: "Acesso Premium Liberado" };
    }
    return { success: false, message: "Evento desconhecido" };
};

