/*
  SERVIDOR BACKEND (Node.js)
  --------------------------
  Este arquivo simula o backend que receberá os dados da Kirvano.

  Para rodar:
  1. Instale dependências: npm install express cors body-parser
  2. Inicie o servidor: node server.js
  3. Exponha para a internet (para a Kirvano acessar): npx ngrok http 3000
*/

const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();
const PORT = 3000;

// Configurações
app.use(cors());
app.use(bodyParser.json());

// "Banco de Dados" em memória (Em produção, use MongoDB/Postgres)
const usersDatabase = {};

// Configuração de Segurança
const SECRET_TOKEN = "agro-token-123"; // O mesmo Token que você configurou na Kirvano

// ROTA 1: WEBHOOK (A Kirvano envia dados para cá)
app.post('/webhook/kirvano', (req, res) => {
    const { event, customer, token } = req.body;

    console.log(`🔔 Webhook Recebido: ${event}`);

    // 1. Validação de Segurança (Opcional, mas recomendado)
    // Verifica se o token enviado bate com o seu, se vier no body ou headers
    // if (req.headers['authorization'] !== SECRET_TOKEN) { ... }

    if (!customer || !customer.email) {
        return res.status(400).json({ error: "Dados do cliente inválidos" });
    }

    const email = customer.email;

    // 2. Processamento do Evento
    if (event === 'sale.approved') {
        console.log(`✅ Pagamento Aprovado para: ${email}`);

        // Atualiza o status do usuário no banco
        usersDatabase[email] = {
            isSubscribed: true,
            plan: 'premium',
            updatedAt: new Date()
        };
    } else if (event === 'sale.refunded' || event === 'sale.chargeback') {
        console.log(`❌ Reembolso/Cancelamento para: ${email}`);

        // Remove acesso
        if (usersDatabase[email]) {
            usersDatabase[email].isSubscribed = false;
        }
    }

    // Resposta 200 OK para a Kirvano saber que recebemos
    res.status(200).json({ received: true });
});

// ROTA 2: API PARA O FRONTEND (Seu site pergunta se o usuário pagou)
app.get('/api/status/:email', (req, res) => {
    const email = req.params.email;
    const user = usersDatabase[email];

    if (user && user.isSubscribed) {
        res.json({ isSubscribed: true });
    } else {
        res.json({ isSubscribed: false });
    }
});

// Inicialização
app.listen(PORT, () => {
    console.log(`🚀 Servidor Backend rodando na porta ${PORT}`);
    console.log(`📡 Endpoint Local: http://localhost:${PORT}/webhook/kirvano`);
    console.log(`\nPARA OBTER A URL HTTPS (KIRVANO):`);
    console.log(`👉 Rode no terminal: npx ngrok http ${PORT}`);
});

import { db } from './databaseService';

// CONFIGURAÇÃO REAL DE PAGAMENTO
export const KIRVANO_CONFIG = {
    // Link do Checkout (Produto)
    CHECKOUT_URL: "https://kirvano.com/checkout/SEU_CODIGO_AQUI", 

    // URL do seu Backend (Local ou Produção)
    // Se estiver rodando o server.js localmente, é http://localhost:3000
    API_BASE_URL: "http://localhost:3000"
};

export interface KirvanoWebhookPayload {
    event: 'sale.approved' | 'sale.refunded' | 'sale.chargeback';
    customer: { email: string };
    token?: string;
}

/**
 * Método 1: Redirecionamento (Frontend Only)
 * Verifica se a URL contém ?status=success
 */
export const checkPaymentRedirect = (): boolean => {
    if (typeof window === 'undefined') return false;

    const params = new URLSearchParams(window.location.search);
    const status = params.get('status');

    if (status === 'success') {
        console.log("Pagamento detectado via URL Redirection");
        const newUrl = window.location.protocol + "//" + window.location.host + window.location.pathname;
        window.history.replaceState({ path: newUrl }, '', newUrl);

        // Libera acesso localmente
        db.user.login();
        localStorage.setItem('agroconectaIsSubscribed', 'true');
        return true;
    }
    return false;
};

/**
 * Método 2: Consulta ao Servidor (Backend Real)
 * Pergunta ao server.js se o email consta como pagante
 */
export const checkSubscriptionStatusFromServer = async (email: string): Promise<boolean> => {
    try {
        const response = await fetch(`${KIRVANO_CONFIG.API_BASE_URL}/api/status/${email}`);
        const data = await response.json();

        if (data.isSubscribed) {
            localStorage.setItem('agroconectaIsSubscribed', 'true');
            return true;
        }
        return false;
    } catch (error) {
        console.warn("Não foi possível conectar ao servidor de pagamentos.", error);
        return false;
    }
};

/**
 * Simulador (Dev Only)
 */
export const processWebhook = async (payload: KirvanoWebhookPayload) => {
    // Simula envio para o servidor local se ele estiver rodando
    try {
        await fetch(`${KIRVANO_CONFIG.API_BASE_URL}/webhook/kirvano`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ...payload, token: 'agro-token-123' })
        });
        return { success: true, message: "Webhook enviado ao Servidor Local" };
    } catch (e) {
        // Fallback local se o servidor estiver desligado
        if (payload.event === 'sale.approved') {
            localStorage.setItem('agroconectaIsSubscribed', 'true');
            return { success: true, message: "Acesso Liberado (Simulação Local)" };
        }
    }
    return { success: false, message: "Erro na simulação" };
};

export const generateTestPayload = (): KirvanoWebhookPayload => {
    return {
        event: 'sale.approved',
        customer: { email: 'teste@agro.com' },
        token: 'agro-token-123'
    };
};

